// Correlación de estados EMA vs Actuador
const items = $input.all();
const ema = items.find(i => i.json.name === 'ema')?.json || {};
const actuador = items.find(i => i.json.name === 'actuador')?.json || {};

let alertType = 'NONE';
let message = '';

if (ema.status === 'offline' && actuador.status === 'offline') {
  alertType = 'APAGÓN_GENERAL';
  message = '⚠️ *ALERTA INFRAESTRUCTURA*\n\nCaída masiva de conectividad. Nodos *EMA* y *Actuador* desconectados.\n\nPosible corte de energía eléctrica o fallo de internet local.';
} else if (ema.status === 'offline' && actuador.status === 'online') {
  alertType = 'BATERÍA_EMA';
  message = '🪫 *ALERTA HARDWARE*\n\nNodo *EMA* OFFLINE (Batería agotada o falla local).\n\nEl nodo *Actuador* permanece ONLINE y funcional.';
} else if (ema.status === 'online') {
  alertType = 'EMA_RESTABLECIDO';
  message = '✅ *NODO RESTABLECIDO*\n\nNodo *EMA* ONLINE.\n\nAlimentación de energía o conectividad restablecida con éxito.';
}

return [{ json: { alertType, message, emaStatus: ema.status, actuadorStatus: actuador.status } }];
